# Step 1: Resolve song IDs using spotify.search_songs (no access_token param)

playlist_title_target = 'Songs for Road Trip'

# Use existing variables: songs_from_email, existing_song_ids, spotify_access_token, playlist_id

spotify_search_page_limit = 20

def normalize(s):
    return (s or '').strip().lower()

def search_songs_all(query):
    page_index = 0
    all_results = []
    while True:
        page = apis.spotify.search_songs(query=query, page_index=page_index, page_limit=spotify_search_page_limit)
        print('search_songs_all query=',query,'page_index=',page_index,'count=',len(page) if page else None)
        if not page:
            break
        all_results.extend(page)
        if len(page) < spotify_search_page_limit:
            break
        page_index += 1
    return all_results

def pick_best_match(results, target_title, target_artist):
    t_title = normalize(target_title)
    t_artist = normalize(target_artist)

    def artist_matches(song):
        return any(normalize(a.get('name')) == t_artist for a in (song.get('artists') or []))

    candidates = [r for r in results if normalize(r.get('title')) == t_title]
    if candidates:
        exact = [r for r in candidates if artist_matches(r)]
        if exact:
            candidates = exact
    else:
        # fallback: title contains
        candidates = [r for r in results if t_title in normalize(r.get('title'))]

    if not candidates:
        return None

    # deterministic scoring
    def score(r):
        return (r.get('like_count', 0) or 0, r.get('play_count', 0) or 0, r.get('rating', 0) or 0)

    return max(candidates, key=score)

resolved = []
for item in songs_from_email:
    title = item['title']
    artist = item['artist']

    results = search_songs_all(f"{title} {artist}")
    best = pick_best_match(results, title, artist)

    if best is None:
        results2 = search_songs_all(title)
        best = pick_best_match(results2, title, artist)

    resolved.append({
        'title': title,
        'artist': artist,
        'resolved_song_id': best['song_id'] if best else None,
        'matched_title': best.get('title') if best else None,
        'matched_artists': [a.get('name') for a in (best.get('artists') or [])] if best else None
    })

print('resolved', resolved)

song_ids_to_add = []
for r in resolved:
    sid = r['resolved_song_id']
    if sid is None:
        continue
    if sid not in existing_song_ids:
        song_ids_to_add.append(sid)

print('existing_song_ids_count', len(existing_song_ids))
print('song_ids_to_add_count', len(song_ids_to_add))
print('song_ids_to_add', song_ids_to_add)

